def count_passing_ways(n: int, m: int) -> int:
    MOD = 1000000007

    # Edge case: If m is 0, the ball is already with the starting student
    if m == 0:
        return 1

    # Edge case: If n is 1, the ball can only be with the starting student
    if n == 1:
        return 0

    # Initialize dp array
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base cases: If there's only one pass
    for i in range(n):
        dp[i][1] = 1

    # Fill the dp array
    for step in range(2, m + 1):
        for student in range(n):
            dp[student][step] = (dp[(student - 1 + n) % n][step - 1] + dp[(student + 1) % n][step - 1]) % MOD

    # The result is the number of ways to end up at the starting student after m passes
    return dp[0][m]

